    { const char * tb_v1170 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1170; }
    { const char * tb_v1171 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v1171; }
