    { const char * tb_v1476 = "TB_API tb_gpage *tb_gall = 0, *tb_glarge = 0, *tb_gavail[2][TB_GNC];\n"; *(const char * *)tb_grow(v_lines) = tb_v1476; }
    { const char * tb_v1477 = "// адрес → страница: таблица в два шага (биты 47..32, потом 31..16)\n"; *(const char * *)tb_grow(v_lines) = tb_v1477; }
    { const char * tb_v1478 = "TB_API tb_gpage **tb_gdir[1 << 16];\n"; *(const char * *)tb_grow(v_lines) = tb_v1478; }
    { const char * tb_v1479 = "TB_API uintptr_t tb_glo = ~(uintptr_t)0, tb_ghi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1479; }
    { const char * tb_v1480 = "TB_API long long tb_gsince = 0, tb_glive = 0, tb_gnext = 8LL << 20, tb_gstress = 0, tb_gcount = 0, tb_gruns = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1480; }
