    { const char * tb_v2854 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2854; }
    { const char * tb_v2855 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2855; }
    { const char * tb_v2856 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2856; }
