    { const char * tb_v3047 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3047; }
    { const char * tb_v3048 = "static void tb_mem_lock(void) { while (__sync_lock_test_and_set(&tb_mem_spin, 1)) { } }\n"; *(const char * *)tb_grow(v_lines) = tb_v3048; }
