    { const char * tb_v3076 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3076; }
    { const char * tb_v3077 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3077; }
    { const char * tb_v3078 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3078; }
