    { const char * tb_v3482 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v3482; }
    { const char * tb_v3483 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3483; }
    { const char * tb_v3484 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v3484; }
    { const char * tb_v3485 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3485; }
    { const char * tb_v3486 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v3486; }
    { const char * tb_v3487 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v3487; }
    { const char * tb_v3488 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3488; }
    { const char * tb_v3489 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3489; }
    { const char * tb_v3490 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3490; }
    { const char * tb_v3491 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3491; }
    { const char * tb_v3492 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3492; }
    { const char * tb_v3493 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3493; }
    { const char * tb_v3494 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3494; }
    { const char * tb_v3495 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3495; }
    { const char * tb_v3496 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v3496; }
    { const char * tb_v3497 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v3497; }
    { const char * tb_v3498 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3498; }
    { const char * tb_v3499 = "TB_API char *tb_gfx_clip_get(void);          // свои у каждой системы: текст (malloc) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v3499; }
    { const char * tb_v3500 = "TB_API void tb_gfx_clip_set(const char *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v3500; }
    { const char * tb_v3501 = "TB_API void tb_gfx_cursor(int k);              // 0 стрелка, 1 рука, 2 текст, 3 двигать, 4 ↔, 5 ↕, 6 ждать, 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v3501; }
    { const char * tb_v3502 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v3502; }
    { const char * tb_v3503 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3503; }
    { const char * tb_v3504 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3504; }
    { const char * tb_v3505 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3505; }
    { const char * tb_v3506 = "    char *o = tb_typed + tb_ntyped;\n"; *(const char * *)tb_grow(v_lines) = tb_v3506; }
    { const char * tb_v3507 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3507; }
    { const char * tb_v3508 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3508; }
    { const char * tb_v3509 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3509; }
    { const char * tb_v3510 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3510; }
    { const char * tb_v3511 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3511; }
    { const char * tb_v3512 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3512; }
    { const char * tb_v3513 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3513; }
    { const char * tb_v3514 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3514; }
    { const char * tb_v3515 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3515; }
    { const char * tb_v3516 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3516; }
    { const char * tb_v3517 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3517; }
    { const char * tb_v3518 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v3518; }
    { const char * tb_v3519 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v3519; }
    { const char * tb_v3520 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3520; }
    { const char * tb_v3521 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v3521; }
    { const char * tb_v3522 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3522; }
    { const char * tb_v3523 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3523; }
    { const char * tb_v3524 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3524; }
    { const char * tb_v3525 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v3525; }
    { const char * tb_v3526 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3526; }
    { const char * tb_v3527 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v3527; }
    { const char * tb_v3528 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v3528; }
    { const char * tb_v3529 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21,\n"; *(const char * *)tb_grow(v_lines) = tb_v3529; }
