    { const char * tb_v3541 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3541; }
    { const char * tb_v3542 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3542; }
