    { const char * tb_v3544 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3544; }
    { const char * tb_v3545 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3545; }
    { const char * tb_v3546 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3546; }
    { const char * tb_v3547 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3547; }
    { const char * tb_v3548 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v3548; }
