    { const char * tb_v3790 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3790; }
    { const char * tb_v3791 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3791; }
