    { const char * tb_v4085 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4085; }
    { const char * tb_v4086 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4086; }
    { const char * tb_v4087 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4087; }
    { const char * tb_v4088 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4088; }
