    { const char * tb_v4091 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4091; }
    { const char * tb_v4092 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v4092; }
    { const char * tb_v4093 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4093; }
    { const char * tb_v4094 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4094; }
    { const char * tb_v4095 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v4095; }
    { const char * tb_v4096 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4096; }
    { const char * tb_v4097 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4097; }
    { const char * tb_v4098 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v4098; }
    { const char * tb_v4099 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4099; }
    { const char * tb_v4100 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v4100; }
    { const char * tb_v4101 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4101; }
    { const char * tb_v4102 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4102; }
    { const char * tb_v4103 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4103; }
    { const char * tb_v4104 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4104; }
    { const char * tb_v4105 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v4105; }
    { const char * tb_v4106 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4106; }
