    { const char * tb_v4109 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4109; }
    { const char * tb_v4110 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v4110; }
    { const char * tb_v4111 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4111; }
    { const char * tb_v4112 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4112; }
    { const char * tb_v4113 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4113; }
    { const char * tb_v4114 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v4114; }
    { const char * tb_v4115 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v4115; }
    { const char * tb_v4116 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v4116; }
    { const char * tb_v4117 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v4117; }
    { const char * tb_v4118 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v4118; }
    { const char * tb_v4119 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4119; }
    { const char * tb_v4120 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v4120; }
    { const char * tb_v4121 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v4121; }
    { const char * tb_v4122 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4122; }
    { const char * tb_v4123 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4123; }
    { const char * tb_v4124 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4124; }
    { const char * tb_v4125 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4125; }
    { const char * tb_v4126 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v4126; }
    { const char * tb_v4127 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4127; }
    { const char * tb_v4128 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4128; }
    { const char * tb_v4129 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4129; }
    { const char * tb_v4130 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v4130; }
    { const char * tb_v4131 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v4131; }
    { const char * tb_v4132 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v4132; }
    { const char * tb_v4133 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4133; }
    { const char * tb_v4134 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v4134; }
    { const char * tb_v4135 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v4135; }
    { const char * tb_v4136 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v4136; }
    { const char * tb_v4137 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v4137; }
    { const char * tb_v4138 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4138; }
    { const char * tb_v4139 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v4139; }
    { const char * tb_v4140 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4140; }
    { const char * tb_v4141 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4141; }
    { const char * tb_v4142 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v4142; }
    { const char * tb_v4143 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v4143; }
    { const char * tb_v4144 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v4144; }
    { const char * tb_v4145 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4145; }
    { const char * tb_v4146 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v4146; }
    { const char * tb_v4147 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v4147; }
    { const char * tb_v4148 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v4148; }
    { const char * tb_v4149 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v4149; }
    { const char * tb_v4150 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4150; }
    { const char * tb_v4151 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4151; }
    { const char * tb_v4152 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v4152; }
    { const char * tb_v4153 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4153; }
    { const char * tb_v4154 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v4154; }
    { const char * tb_v4155 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v4155; }
    { const char * tb_v4156 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4156; }
    { const char * tb_v4157 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v4157; }
    { const char * tb_v4158 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v4158; }
    { const char * tb_v4159 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4159; }
    { const char * tb_v4160 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v4160; }
    { const char * tb_v4161 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4161; }
    { const char * tb_v4162 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v4162; }
    { const char * tb_v4163 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v4163; }
    { const char * tb_v4164 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4164; }
    { const char * tb_v4165 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4165; }
    { const char * tb_v4166 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v4166; }
    { const char * tb_v4167 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4167; }
    { const char * tb_v4168 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v4168; }
    { const char * tb_v4169 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4169; }
    { const char * tb_v4170 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4170; }
    { const char * tb_v4171 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4171; }
    { const char * tb_v4172 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v4172; }
    { const char * tb_v4173 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4173; }
    { const char * tb_v4174 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4174; }
    { const char * tb_v4175 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v4175; }
    { const char * tb_v4176 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4176; }
    { const char * tb_v4177 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v4177; }
    { const char * tb_v4178 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v4178; }
    { const char * tb_v4179 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4179; }
    { const char * tb_v4180 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v4180; }
    { const char * tb_v4181 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v4181; }
    { const char * tb_v4182 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4182; }
    { const char * tb_v4183 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4183; }
    { const char * tb_v4184 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4184; }
    { const char * tb_v4185 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4185; }
    { const char * tb_v4186 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4186; }
    { const char * tb_v4187 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4187; }
    { const char * tb_v4188 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4188; }
    { const char * tb_v4189 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4189; }
    { const char * tb_v4190 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v4190; }
    { const char * tb_v4191 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v4191; }
    { const char * tb_v4192 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4192; }
    { const char * tb_v4193 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4193; }
    { const char * tb_v4194 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4194; }
    { const char * tb_v4195 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4195; }
    { const char * tb_v4196 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4196; }
    { const char * tb_v4197 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v4197; }
    { const char * tb_v4198 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4198; }
    { const char * tb_v4199 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4199; }
    { const char * tb_v4200 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4200; }
    { const char * tb_v4201 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v4201; }
    { const char * tb_v4202 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4202; }
    { const char * tb_v4203 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4203; }
    { const char * tb_v4204 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4204; }
    { const char * tb_v4205 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v4205; }
    { const char * tb_v4206 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4206; }
