    { const char * tb_v6793 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v6793; }
    { const char * tb_v6794 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v6794; }
    { const char * tb_v6795 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6795; }
    { const char * tb_v6796 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6796; }
