    { const char * tb_v6997 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6997; }
    { const char * tb_v6998 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6998; }
    { const char * tb_v6999 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6999; }
