    { const char * tb_v7035 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7035; }
    { const char * tb_v7036 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7036; }
