    { const char * tb_v7046 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7046; }
    { const char * tb_v7047 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v7047; }
    { const char * tb_v7048 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7048; }
    { const char * tb_v7049 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7049; }
    { const char * tb_v7050 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7050; }
    { const char * tb_v7051 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7051; }
    { const char * tb_v7052 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v7052; }
    { const char * tb_v7053 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7053; }
    { const char * tb_v7054 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7054; }
    { const char * tb_v7055 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v7055; }
    { const char * tb_v7056 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7056; }
    { const char * tb_v7057 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v7057; }
    { const char * tb_v7058 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v7058; }
    { const char * tb_v7059 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7059; }
    { const char * tb_v7060 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v7060; }
    { const char * tb_v7061 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v7061; }
    { const char * tb_v7062 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v7062; }
    { const char * tb_v7063 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7063; }
    { const char * tb_v7064 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7064; }
    { const char * tb_v7065 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7065; }
    { const char * tb_v7066 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v7066; }
    { const char * tb_v7067 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v7067; }
    { const char * tb_v7068 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v7068; }
    { const char * tb_v7069 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7069; }
    { const char * tb_v7070 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7070; }
    { const char * tb_v7071 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v7071; }
    { const char * tb_v7072 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7072; }
    { const char * tb_v7073 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v7073; }
    { const char * tb_v7074 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7074; }
    { const char * tb_v7075 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7075; }
    { const char * tb_v7076 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7076; }
    { const char * tb_v7077 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v7077; }
    { const char * tb_v7078 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7078; }
    { const char * tb_v7079 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7079; }
    { const char * tb_v7080 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7080; }
    { const char * tb_v7081 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v7081; }
    { const char * tb_v7082 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v7082; }
    { const char * tb_v7083 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7083; }
    { const char * tb_v7084 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7084; }
    { const char * tb_v7085 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v7085; }
    { const char * tb_v7086 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v7086; }
    { const char * tb_v7087 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7087; }
    { const char * tb_v7088 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v7088; }
    { const char * tb_v7089 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v7089; }
    { const char * tb_v7090 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v7090; }
    { const char * tb_v7091 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v7091; }
    { const char * tb_v7092 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v7092; }
    { const char * tb_v7093 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v7093; }
    { const char * tb_v7094 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v7094; }
    { const char * tb_v7095 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v7095; }
    { const char * tb_v7096 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7096; }
    { const char * tb_v7097 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7097; }
    { const char * tb_v7098 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v7098; }
    { const char * tb_v7099 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v7099; }
    { const char * tb_v7100 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7100; }
    { const char * tb_v7101 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7101; }
    { const char * tb_v7102 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7102; }
    { const char * tb_v7103 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7103; }
    { const char * tb_v7104 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7104; }
    { const char * tb_v7105 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v7105; }
    { const char * tb_v7106 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7106; }
    { const char * tb_v7107 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7107; }
    { const char * tb_v7108 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7108; }
    { const char * tb_v7109 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7109; }
    { const char * tb_v7110 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7110; }
    { const char * tb_v7111 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7111; }
    { const char * tb_v7112 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7112; }
    { const char * tb_v7113 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7113; }
    { const char * tb_v7114 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7114; }
    { const char * tb_v7115 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v7115; }
    { const char * tb_v7116 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7116; }
    { const char * tb_v7117 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v7117; }
    { const char * tb_v7118 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7118; }
    { const char * tb_v7119 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v7119; }
    { const char * tb_v7120 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7120; }
    { const char * tb_v7121 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7121; }
    { const char * tb_v7122 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7122; }
    { const char * tb_v7123 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7123; }
    { const char * tb_v7124 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7124; }
    { const char * tb_v7125 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7125; }
    { const char * tb_v7126 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7126; }
    { const char * tb_v7127 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7127; }
    { const char * tb_v7128 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7128; }
    { const char * tb_v7129 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7129; }
    { const char * tb_v7130 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7130; }
    { const char * tb_v7131 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v7131; }
    { const char * tb_v7132 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7132; }
    { const char * tb_v7133 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7133; }
    { const char * tb_v7134 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7134; }
    { const char * tb_v7135 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7135; }
    { const char * tb_v7136 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7136; }
    { const char * tb_v7137 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7137; }
    { const char * tb_v7138 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7138; }
    { const char * tb_v7139 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7139; }
    { const char * tb_v7140 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7140; }
    { const char * tb_v7141 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7141; }
    { const char * tb_v7142 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7142; }
    { const char * tb_v7143 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v7143; }
    { const char * tb_v7144 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v7144; }
    { const char * tb_v7145 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7145; }
    { const char * tb_v7146 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7146; }
    { const char * tb_v7147 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v7147; }
    { const char * tb_v7148 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7148; }
    { const char * tb_v7149 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7149; }
    { const char * tb_v7150 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v7150; }
    { const char * tb_v7151 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7151; }
    { const char * tb_v7152 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7152; }
    { const char * tb_v7153 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v7153; }
    { const char * tb_v7154 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v7154; }
    { const char * tb_v7155 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7155; }
    { const char * tb_v7156 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7156; }
    { const char * tb_v7157 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7157; }
    { const char * tb_v7158 = "    m->chok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7158; }
    { const char * tb_v7159 = "    if (m->n == m->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7159; }
    { const char * tb_v7160 = "        m->cap = m->cap ? m->cap * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7160; }
    { const char * tb_v7161 = "        m->t = (uint32_t *)realloc(m->t, sizeof(uint32_t) * 3 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v7161; }
    { const char * tb_v7162 = "        m->c = (uint32_t *)realloc(m->c, sizeof(uint32_t) * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v7162; }
    { const char * tb_v7163 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7163; }
    { const char * tb_v7164 = "    uint32_t *t = m->t + 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7164; }
    { const char * tb_v7165 = "    t[0] = tb_mesh_vertex(m, x1, y1, z1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7165; }
    { const char * tb_v7166 = "    t[1] = tb_mesh_vertex(m, x2, y2, z2);\n"; *(const char * *)tb_grow(v_lines) = tb_v7166; }
    { const char * tb_v7167 = "    t[2] = tb_mesh_vertex(m, x3, y3, z3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7167; }
    { const char * tb_v7168 = "    m->c[m->n++] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7168; }
    { const char * tb_v7169 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7169; }
    { const char * tb_v7170 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7170; }
    { const char * tb_v7171 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7171; }
    { const char * tb_v7172 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v7172; }
    { const char * tb_v7173 = "    for (int i = 0; i < 3; i++) f[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7173; }
    { const char * tb_v7174 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7174; }
    { const char * tb_v7175 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v7175; }
    { const char * tb_v7176 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v7176; }
    { const char * tb_v7177 = "    l = sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7177; }
    { const char * tb_v7178 = "    for (int i = 0; i < 3; i++) r[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7178; }
    { const char * tb_v7179 = "    double u[3] = { f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v7179; }
    { const char * tb_v7180 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7180; }
