    { const char * tb_v7220 = "    for (long long t = t0; t < t1; t++) for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7220; }
    { const char * tb_v7221 = "        long long k = m->t[3 * t + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7221; }
