    { const char * tb_v7264 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7264; }
    { const char * tb_v7265 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7265; }
