    { const char * tb_v7271 = "            sx[i] = hw + f * qx[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7271; }
    { const char * tb_v7272 = "            sy[i] = hh - f * qy[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
