    { const char * tb_v7295 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7295; }
    { const char * tb_v7296 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v7296; }
    { const char * tb_v7297 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v7297; }
    { const char * tb_v7298 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7298; }
    { const char * tb_v7299 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7299; }
    { const char * tb_v7300 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7300; }
    { const char * tb_v7301 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7301; }
    { const char * tb_v7302 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7302; }
    { const char * tb_v7303 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v7303; }
    { const char * tb_v7304 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7304; }
    { const char * tb_v7305 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v7305; }
    { const char * tb_v7306 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7306; }
    { const char * tb_v7307 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7307; }
    { const char * tb_v7308 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7308; }
    { const char * tb_v7309 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v7309; }
    { const char * tb_v7310 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v7310; }
    { const char * tb_v7311 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v7311; }
    { const char * tb_v7312 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7312; }
    { const char * tb_v7313 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7313; }
    { const char * tb_v7314 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v7314; }
    { const char * tb_v7315 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7315; }
    { const char * tb_v7316 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7316; }
    { const char * tb_v7317 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7317; }
    { const char * tb_v7318 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7318; }
    { const char * tb_v7319 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7319; }
    { const char * tb_v7320 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v7320; }
    { const char * tb_v7321 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7321; }
    { const char * tb_v7322 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7322; }
    { const char * tb_v7323 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7323; }
    { const char * tb_v7324 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7324; }
    { const char * tb_v7325 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7325; }
    { const char * tb_v7326 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7326; }
    { const char * tb_v7327 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7327; }
    { const char * tb_v7328 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7328; }
    { const char * tb_v7329 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7329; }
    { const char * tb_v7330 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7330; }
    { const char * tb_v7331 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v7331; }
    { const char * tb_v7332 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v7332; }
    { const char * tb_v7333 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7333; }
    { const char * tb_v7334 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7334; }
    { const char * tb_v7335 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v7335; }
    { const char * tb_v7336 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7336; }
    { const char * tb_v7337 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7337; }
    { const char * tb_v7338 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7338; }
    { const char * tb_v7339 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v7339; }
    { const char * tb_v7340 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7340; }
    { const char * tb_v7341 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7341; }
    { const char * tb_v7342 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7342; }
    { const char * tb_v7343 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7343; }
    { const char * tb_v7344 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v7344; }
    { const char * tb_v7345 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7345; }
    { const char * tb_v7346 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7346; }
    { const char * tb_v7347 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7347; }
    { const char * tb_v7348 = "                int32_t *o = dst + 4 * (m->gt + t);\n"; *(const char * *)tb_grow(v_lines) = tb_v7348; }
    { const char * tb_v7349 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7349; }
    { const char * tb_v7350 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v7350; }
    { const char * tb_v7351 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7351; }
    { const char * tb_v7352 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7352; }
    { const char * tb_v7353 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7353; }
    { const char * tb_v7354 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7354; }
    { const char * tb_v7355 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v7355; }
    { const char * tb_v7356 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7356; }
    { const char * tb_v7357 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7357; }
    { const char * tb_v7358 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7358; }
    { const char * tb_v7359 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7359; }
    { const char * tb_v7360 = "    pc->tbase = (int32_t)(m->gt + g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v7360; }
    { const char * tb_v7361 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7361; }
    { const char * tb_v7362 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7362; }
    { const char * tb_v7363 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v7363; }
    { const char * tb_v7364 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7364; }
    { const char * tb_v7365 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v7365; }
    { const char * tb_v7366 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v7366; }
    { const char * tb_v7367 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7367; }
    { const char * tb_v7368 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7368; }
    { const char * tb_v7369 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v7369; }
    { const char * tb_v7370 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7370; }
    { const char * tb_v7371 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7371; }
    { const char * tb_v7372 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7372; }
    { const char * tb_v7373 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7373; }
    { const char * tb_v7374 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v7374; }
    { const char * tb_v7375 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7375; }
    { const char * tb_v7376 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v7376; }
    { const char * tb_v7377 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v7377; }
    { const char * tb_v7378 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7378; }
    { const char * tb_v7379 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7379; }
    { const char * tb_v7380 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v7380; }
    { const char * tb_v7381 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v7381; }
    { const char * tb_v7382 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v7382; }
    { const char * tb_v7383 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7383; }
    { const char * tb_v7384 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v7384; }
    { const char * tb_v7385 = "    if (tb_gpu_on && tb_gpu_mesh) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v7385; }
    { const char * tb_v7386 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7386; }
    { const char * tb_v7387 = "        if (go->rbatch != tb_gbatch) {   // запись этого вызова ещё не в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v7387; }
    { const char * tb_v7388 = "            go->ri = tb_grn++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7388; }
