    { const char * tb_v7398 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7398; }
    { const char * tb_v7399 = "    // процессор: та же целая формула (кадр для сверки, или видеокарта без своего 3D, или без видеокарты)\n"; *(const char * *)tb_grow(v_lines) = tb_v7399; }
    { const char * tb_v7400 = "    int gpu = tb_gpu_on && !tb_gpu_mesh, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v7400; }
