    { const char * tb_v7404 = "        tb_3ist = (long long *)realloc(tb_3ist, sizeof(long long) * tb_3icap / 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7404; }
    { const char * tb_v7405 = "        memset(tb_3ist, 0, sizeof(long long) * (tb_3icap / 3));\n"; *(const char * *)tb_grow(v_lines) = tb_v7405; }
    { const char * tb_v7406 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7406; }
    { const char * tb_v7407 = "    long long fq = tb_m3_f(), gen = ++tb_3igen;\n"; *(const char * *)tb_grow(v_lines) = tb_v7407; }
    { const char * tb_v7408 = "    for (long long t = t0; t < t0 + tn; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7408; }
    { const char * tb_v7409 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7409; }
    { const char * tb_v7410 = "        for (int i = 0; i < 3; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7410; }
    { const char * tb_v7411 = "            if (tb_3ist[ti[i]] != gen) { tb_3ist[ti[i]] = gen; tb_m3_corner(go->rec.r, m->vi + 4 * ti[i], fq, tb_3i + 3 * ti[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7411; }
    { const char * tb_v7412 = "        long long q[6];\n"; *(const char * *)tb_grow(v_lines) = tb_v7412; }
    { const char * tb_v7413 = "        uint32_t pl[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7413; }
