    { const char * tb_v7574 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7574; }
    { const char * tb_v7575 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7575; }
    { const char * tb_v7576 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v7576; }
    { const char * tb_v7577 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v7577; }
    { const char * tb_v7578 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v7578; }
    { const char * tb_v7579 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v7579; }
    { const char * tb_v7580 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7580; }
    { const char * tb_v7581 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v7581; }
    { const char * tb_v7582 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v7582; }
    { const char * tb_v7583 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v7583; }
    { const char * tb_v7584 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v7584; }
    { const char * tb_v7585 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v7585; }
    { const char * tb_v7586 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v7586; }
    { const char * tb_v7587 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v7587; }
    { const char * tb_v7588 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v7588; }
    { const char * tb_v7589 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v7589; }
    { const char * tb_v7590 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v7590; }
    { const char * tb_v7591 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7591; }
    { const char * tb_v7592 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7592; }
    { const char * tb_v7593 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v7593; }
    { const char * tb_v7594 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v7594; }
    { const char * tb_v7595 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v7595; }
    { const char * tb_v7596 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7596; }
    { const char * tb_v7597 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v7597; }
    { const char * tb_v7598 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7598; }
    { const char * tb_v7599 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7599; }
    { const char * tb_v7600 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v7600; }
    { const char * tb_v7601 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7601; }
    { const char * tb_v7602 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v7602; }
    { const char * tb_v7603 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v7603; }
    { const char * tb_v7604 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7604; }
    { const char * tb_v7605 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v7605; }
    { const char * tb_v7606 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v7606; }
    { const char * tb_v7607 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v7607; }
    { const char * tb_v7608 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7608; }
    { const char * tb_v7609 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7609; }
    { const char * tb_v7610 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7610; }
    { const char * tb_v7611 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v7611; }
    { const char * tb_v7612 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7612; }
    { const char * tb_v7613 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7613; }
    { const char * tb_v7614 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7614; }
    { const char * tb_v7615 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7615; }
    { const char * tb_v7616 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7616; }
    { const char * tb_v7617 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7617; }
    { const char * tb_v7618 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7618; }
    { const char * tb_v7619 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v7619; }
    { const char * tb_v7620 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7620; }
    { const char * tb_v7621 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v7621; }
    { const char * tb_v7622 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7622; }
    { const char * tb_v7623 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v7623; }
    { const char * tb_v7624 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v7624; }
    { const char * tb_v7625 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7625; }
    { const char * tb_v7626 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7626; }
    { const char * tb_v7627 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7627; }
    { const char * tb_v7628 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7628; }
    { const char * tb_v7629 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7629; }
    { const char * tb_v7630 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7630; }
    { const char * tb_v7631 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v7631; }
    { const char * tb_v7632 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7632; }
    { const char * tb_v7633 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7633; }
    { const char * tb_v7634 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v7634; }
    { const char * tb_v7635 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7635; }
    { const char * tb_v7636 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7636; }
    { const char * tb_v7637 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7637; }
    { const char * tb_v7638 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7638; }
    { const char * tb_v7639 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7639; }
    { const char * tb_v7640 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v7640; }
    { const char * tb_v7641 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7641; }
    { const char * tb_v7642 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7642; }
    { const char * tb_v7643 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v7643; }
    { const char * tb_v7644 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7644; }
    { const char * tb_v7645 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7645; }
    { const char * tb_v7646 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7646; }
    { const char * tb_v7647 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7647; }
    { const char * tb_v7648 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7648; }
    { const char * tb_v7649 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v7649; }
    { const char * tb_v7650 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v7650; }
    { const char * tb_v7651 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v7651; }
    { const char * tb_v7652 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7652; }
    { const char * tb_v7653 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7653; }
    { const char * tb_v7654 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v7654; }
    { const char * tb_v7655 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7655; }
    { const char * tb_v7656 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7656; }
    { const char * tb_v7657 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7657; }
    { const char * tb_v7658 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7658; }
    { const char * tb_v7659 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v7659; }
    { const char * tb_v7660 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7660; }
    { const char * tb_v7661 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7661; }
    { const char * tb_v7662 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7662; }
    { const char * tb_v7663 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v7663; }
    { const char * tb_v7664 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7664; }
    { const char * tb_v7665 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7665; }
    { const char * tb_v7666 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v7666; }
    { const char * tb_v7667 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v7667; }
    { const char * tb_v7668 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v7668; }
    { const char * tb_v7669 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7669; }
    { const char * tb_v7670 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7670; }
    { const char * tb_v7671 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7671; }
    { const char * tb_v7672 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7672; }
    { const char * tb_v7673 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7673; }
    { const char * tb_v7674 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v7674; }
    { const char * tb_v7675 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7675; }
    { const char * tb_v7676 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v7676; }
    { const char * tb_v7677 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v7677; }
    { const char * tb_v7678 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7678; }
    { const char * tb_v7679 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v7679; }
    { const char * tb_v7680 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7680; }
    { const char * tb_v7681 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7681; }
    { const char * tb_v7682 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7682; }
    { const char * tb_v7683 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7683; }
    { const char * tb_v7684 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7684; }
    { const char * tb_v7685 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v7685; }
    { const char * tb_v7686 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7686; }
    { const char * tb_v7687 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7687; }
    { const char * tb_v7688 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7688; }
    { const char * tb_v7689 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7689; }
    { const char * tb_v7690 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7690; }
    { const char * tb_v7691 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7691; }
    { const char * tb_v7692 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7692; }
    { const char * tb_v7693 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7693; }
    { const char * tb_v7694 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7694; }
    { const char * tb_v7695 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7695; }
